1131|         }
1132|         if (isInfinite()) {
1133|             result.add(INF);
1134|             return result;
1135|         }
1136| 
1137|         // nth root of abs -- faster / more accurate to use a solver here?
1138|         final double nthRootOfAbs = FastMath.pow(abs(), 1.0 / n);
1139| 
1140|         // Compute nth roots of complex number with k = 0, 1, ... n-1
1141|         final double nthPhi = getArgument() / n;
1142|         final double slice = 2 * FastMath.PI / n;
1143|         double innerPart = nthPhi;
1144|         for (int k = 0; k < n ; k++) {
1145|             // inner part
1146|             final double realPart = nthRootOfAbs *  FastMath.cos(innerPart);
1147|             final double imaginaryPart = nthRootOfAbs *  FastMath.sin(innerPart);
1148|             result.add(createComplex(realPart, imaginaryPart));
1149|             innerPart += slice;
1150|         }
1151| 
1152|         return result;
1153|     }
